# planet-hunter web API
# Serves the published results in data/results.json and data/method.json.
# Those files are generated by scripts/build_results.py from the pipeline's
# CSV plus human annotations; nothing here is hardcoded and nothing here runs
# a live MAST scan.
from __future__ import annotations

import logging
import os
from contextlib import asynccontextmanager

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse

import data_store
from security_mw import SecurityMiddleware
from api_v2 import classroom_router as v2_classroom_router
from api_v2 import learn_router as v2_learn_router
from api_v2 import live_router as v2_live_router
from api_v2 import phase4_router as v2_phase4_router
from api_v2 import phase5_router as v2_phase5_router
from api_v2 import phase9_router as v2_phase9_router
from api_v2 import scan_router as v2_scan_router
from api_v2 import router as v2_router
from schemas import (
    Candidate,
    CandidatesResponse,
    HealthResponse,
    MethodResponse,
    OverviewResponse,
    Validation,
)

VERSION = "1.1.0"
log = logging.getLogger("planet-hunter")


def allowed_origins() -> list[str]:
    """Comma-separated ALLOWED_ORIGINS, e.g. the production frontend URL.

    Local development origins are always allowed.
    """
    extra = [o.strip() for o in os.environ.get("ALLOWED_ORIGINS", "").split(",") if o.strip()]
    return ["http://localhost:3000", "http://127.0.0.1:3000", *extra]


def sync_lessons() -> None:
    """Copy content/lessons/ into Postgres. A missing or unready database only affects /api/v2/lessons."""
    import db
    from learn import store

    eng = db.engine()
    if eng is None:
        return
    try:
        n = store.sync(eng)
        log.info("lessons synced: %d written", n)
    except Exception as exc:  # noqa: BLE001 - startup must not fail on the database
        log.warning("lessons not synced: %s", exc)
    try:
        gone = store.purge_stale_progress(eng)
        if gone:
            log.info("learn progress untouched for 24 months removed: %d", gone)
    except Exception as exc:  # noqa: BLE001 - the table may not exist yet on an older database
        log.warning("stale learn progress not purged: %s", exc)


@asynccontextmanager
async def lifespan(_: FastAPI):
    data_store.check_integrity()
    sync_lessons()
    yield


app = FastAPI(title="planet-hunter API", version=VERSION, lifespan=lifespan)

app.add_middleware(SecurityMiddleware)
app.add_middleware(
    CORSMiddleware,
    allow_origins=allowed_origins(),
    allow_methods=["GET", "POST", "PUT", "DELETE"],
    allow_headers=["*"],
)

app.include_router(v2_router)
app.include_router(v2_live_router)
app.include_router(v2_phase4_router)
app.include_router(v2_phase5_router)
app.include_router(v2_scan_router)
app.include_router(v2_learn_router)
app.include_router(v2_classroom_router)
app.include_router(v2_phase9_router)


@app.get("/api/health", response_model=HealthResponse)
def health() -> HealthResponse:
    r = data_store.results()
    return HealthResponse(
        status="ok",
        service="planet-hunter-api",
        version=VERSION,
        schema_version=r.schema_version,
        run_date=r.run.run_date,
        candidate_count=r.summary.count,
    )


@app.get("/api/overview", response_model=OverviewResponse)
def overview() -> OverviewResponse:
    r = data_store.results()
    return OverviewResponse(run=r.run, honesty=r.honesty, summary=r.summary, validation=r.validation)


@app.get("/api/validation", response_model=Validation)
def validation() -> Validation:
    return data_store.results().validation


@app.get("/api/candidates", response_model=CandidatesResponse)
def candidates() -> CandidatesResponse:
    r = data_store.results()
    return CandidatesResponse(run=r.run, honesty=r.honesty, summary=r.summary, candidates=r.candidates)


@app.get("/api/candidates/{slug}", response_model=Candidate)
def candidate(slug: str) -> Candidate:
    for c in data_store.results().candidates:
        if c.slug == slug:
            return c
    raise HTTPException(status_code=404, detail=f"unknown candidate slug: {slug}")


@app.get("/api/method", response_model=MethodResponse)
def method() -> MethodResponse:
    return data_store.method()


@app.get("/api/plots/{filename}")
def plot(filename: str):
    path = data_store.plot_path(filename)
    if path is None:
        raise HTTPException(status_code=404, detail=f"unknown plot file: {filename}")
    return FileResponse(path, media_type="image/png", headers={"Cache-Control": "public, max-age=86400"})
